#!/usr/bin/env bash\n# Mock rationale: This script validates that the Terraform module contains the expected resources.\nset -e\n\n# Check that main.tf defines aws_s3_bucket\nif ! grep -q 'resource \"aws_s3_bucket\"' src/main.tf; then\n  echo "Missing aws_s3_bucket resource"\n  exit 1\nfi\n\n# Check versioning resource\nif ! grep -q 'resource \"aws_s3_bucket_versioning\"' src/main.tf; then\n  echo "Missing aws_s3_bucket_versioning resource"\n  exit 1\nfi\n\n# Check lifecycle configuration\nif ! grep -q 'resource \"aws_s3_bucket_lifecycle_configuration\"' src/main.tf; then\n  echo "Missing aws_s3_bucket_lifecycle_configuration resource"\n  exit 1\nfi\n\n# Check variable definition\nif ! grep -q 'variable \"bucket_name\"' src/variables.tf; then\n  echo "Missing bucket_name variable"\n  exit 1\nfi\n\necho "All checks passed."\n
